def _random_dfa(n):
    _delta = {}
    for _q in range(n):
        for _s in "ab":
            _delta[(_q, _s)] = _rng.randrange(n)
    return DFA(set(range(n)), "ab", _delta, 0,
               {_q for _q in range(n) if _rng.random() < 0.4})


